"""Build a dependency-free XLSX template: blank product sheet and separate examples/help."""
import pathlib,zipfile
from xml.sax.saxutils import escape
ROOT=pathlib.Path(__file__).resolve().parents[1]
COLS=['sku','nombre','categoria','precio','costo','iva','control_inventario','existencia','stock_minimo','unidad','cantidad_minima','incremento','decimales','descripcion','estado']
def workbook(path,products=None):
    help_rows=[['FISITAAP · Crear productos desde Excel'],['Completa únicamente la hoja Productos. Ejemplos e Instrucciones no se importan.'],['Máximo 500 productos y 5 MB. No cambies los encabezados. Guarda como .xlsx o CSV UTF-8.'],['Esta carga crea productos nuevos. SKU existente o repetido rechaza toda la carga.'],['Revisa la vista previa y confirma Crear productos. Un error impide guardar todas las filas.'],['Columna','Uso / valores predeterminados'],['sku','Obligatorio. Código único de hasta 80 caracteres. Formato Texto conserva ceros iniciales.'],['nombre','Obligatorio. Hasta 190 caracteres.'],['categoria','Opcional. Hasta 120 caracteres. Una categoría nueva se crea en tu negocio.'],['precio','Obligatorio. Número sin símbolo de moneda ni separador de miles; hasta 2 decimales. Respeta la configuración de impuestos de tu negocio.'],['costo','Opcional. 0 por defecto; hasta 4 decimales.'],['iva','Opcional. 0 por defecto; porcentaje entre 0 y 100, hasta 2 decimales.'],['control_inventario','Si o No. No por defecto. Si registras existencia o mínimo, indica Si.'],['existencia','Opcional. 0 por defecto; hasta 3 decimales. Se carga solo en la sucursal elegida.'],['stock_minimo','Opcional. 0 por defecto; hasta 3 decimales.'],['unidad','Opcional. unidad por defecto; ejemplo kg o pieza. Hasta 40 caracteres.'],['cantidad_minima','Opcional. 1 por defecto. Mayor que 0 y acorde a decimales.'],['incremento','Opcional. 1 por defecto. Mayor que 0 y acorde a decimales.'],['decimales','Opcional. 0 por defecto. Entero entre 0 y 3 para venta por cantidad.'],['descripcion','Opcional. Texto de hasta 2000 caracteres.'],['estado','Activo, Oculto o Agotado. Activo por defecto.'],['Importante','Usa valores, no fórmulas. No incluyas contraseñas, imágenes ni enlaces de imágenes.'],['Sucursales','En catálogo global, los productos son del negocio; en modo por sucursal se habilitan en la elegida. Las existencias de otras sucursales no cambian.'],['Permisos','Necesitas crear productos; para inventario o categorías nuevas, también sus permisos correspondientes.']]
    examples=[COLS,['0001','Camiseta','Ropa',8500,4200,13,'Si',20,3,'unidad',1,1,0,'Camiseta de algodón','Activo'],['PESO-001','Café en grano','Alimentos',12000,6000,1,'Si',10.5,2,'kg',0.25,0.25,2,'Venta por peso','Activo']]
    def sheet(rows,table=False):
        xml=['<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>']
        for i in range(1,16 if table else 3):xml.append(f'<col min="{i}" max="{i}" width="{24 if table else (30 if i==1 else 105)}" customWidth="1"'+(' style="2"' if table and i==1 else '')+'/>')
        xml.append('</cols><sheetData>')
        for r,row in enumerate(rows,1):
            xml.append(f'<row r="{r}">')
            for c,v in enumerate(row):
                name=chr(65+c)+str(r);style=1 if r==1 else (2 if c==0 and table else 0)
                if isinstance(v,(int,float)):xml.append(f'<c r="{name}" s="{style}"><v>{v}</v></c>')
                else:xml.append(f'<c r="{name}" s="{style}" t="inlineStr"><is><t xml:space="preserve">{escape(str(v))}</t></is></c>')
            xml.append('</row>')
        xml.append('</sheetData>')
        if table:xml.append('<autoFilter ref="A1:O501"/><dataValidations count="2"><dataValidation type="list" allowBlank="1" sqref="G2:G501"><formula1>"Si,No"</formula1></dataValidation><dataValidation type="list" allowBlank="1" sqref="O2:O501"><formula1>"Activo,Oculto,Agotado"</formula1></dataValidation></dataValidations>')
        xml.append('</worksheet>');return ''.join(xml)
    path.parent.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED) as z:
        z.writestr('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+''.join(f'<Override PartName="/xl/worksheets/sheet{i}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>' for i in range(1,4))+'</Types>')
        z.writestr('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
        z.writestr('xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+''.join(f'<sheet name="{n}" sheetId="{i}" r:id="rId{i}"/>' for i,n in enumerate(['Productos','Ejemplos','Instrucciones'],1))+'</sheets></workbook>')
        z.writestr('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+''.join(f'<Relationship Id="rId{i}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{i}.xml"/>' for i in range(1,4))+'<Relationship Id="styles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>')
        z.writestr('xl/styles.xml','<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF203F57"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFill="1" applyFont="1"/><xf numFmtId="49" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>')
        for i,rows in enumerate([[COLS]+(products or []),examples,help_rows],1):z.writestr(f'xl/worksheets/sheet{i}.xml',sheet(rows,i<3))
if __name__=='__main__':
    file=ROOT/'actualizaciones/1.8.0/web/assets/machote-productos.xlsx';workbook(file);print('Template',file.stat().st_size,'bytes, empty Products + separate Examples/Instructions')
